#!/usr/bin/env python3
# aggregate_ktp_eval_runs.py
#
# Aggregates multiple KTP_eval_run JSON outputs into:
#   - one flat CSV with all rows
#   - one flat JSON
#   - one ranked CSV for seq == ALL
#   - one best-per-backend CSV
#
# Expected input:
#   A directory containing JSON files generated by KTP_eval_run.py
#
# Example:
# python .\demo\aggregate_ktp_eval_runs.py ^
#   --input_dir "C:\Users\inesg\OneDrive\Desktop\Thesis\datasets\full_model_eval_final3" ^
#   --out_dir "C:\Users\inesg\OneDrive\Desktop\Thesis\datasets\full_model_eval_final3\aggregated"

import json
import csv
import argparse
from pathlib import Path
from typing import Any, Dict, List, Optional


def safe_mkdir(p: Path) -> None:
    p.mkdir(parents=True, exist_ok=True)


def load_json(path: Path) -> Optional[Dict[str, Any]]:
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception as e:
        print(f"[warn] Failed to read {path.name}: {e}")
        return None


def is_eval_json(payload: Dict[str, Any]) -> bool:
    return isinstance(payload, dict) and "overall" in payload and "per_sequence" in payload


def normalize_row(row: Dict[str, Any], source_json: Path) -> Dict[str, Any]:
    out = dict(row)
    out["source_json"] = str(source_json)
    return out


def sort_key_overall(row: Dict[str, Any]):
    """
    Ranking rule:
      1) higher mota
      2) lower id_switches
      3) higher recall
      4) higher precision
      5) lower reacq_mean_frames
    """
    mota = float(row.get("mota", 0.0))
    idsw = float(row.get("id_switches", 1e18))
    recall = float(row.get("recall", 0.0))
    precision = float(row.get("precision", 0.0))
    reacq_mean = float(row.get("reacq_mean_frames", 1e18))
    return (-mota, idsw, -recall, -precision, reacq_mean)


def choose_best_per_backend(rows_all: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    best_rows = []
    by_backend: Dict[str, List[Dict[str, Any]]] = {}

    for row in rows_all:
        backend = str(row.get("reid_backend", "unknown"))
        by_backend.setdefault(backend, []).append(row)

    for backend, rows in by_backend.items():
        rows_sorted = sorted(rows, key=sort_key_overall)
        best_rows.append(rows_sorted[0])

    best_rows = sorted(best_rows, key=sort_key_overall)
    return best_rows


def collect_all_rows(input_dir: Path) -> List[Dict[str, Any]]:
    json_files = sorted(input_dir.glob("*.json"))
    all_rows: List[Dict[str, Any]] = []

    for fp in json_files:
        payload = load_json(fp)
        if payload is None:
            continue
        if not is_eval_json(payload):
            continue

        per_seq = payload.get("per_sequence", [])
        overall = payload.get("overall", None)

        if isinstance(per_seq, list):
            for row in per_seq:
                if isinstance(row, dict):
                    all_rows.append(normalize_row(row, fp))

        if isinstance(overall, dict):
            all_rows.append(normalize_row(overall, fp))

    return all_rows


def write_csv(rows: List[Dict[str, Any]], out_path: Path) -> None:
    if not rows:
        print(f"[warn] No rows to write to {out_path}")
        return

    fieldnames = []
    seen = set()
    for row in rows:
        for k in row.keys():
            if k not in seen:
                seen.add(k)
                fieldnames.append(k)

    with out_path.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fieldnames)
        w.writeheader()
        for row in rows:
            w.writerow(row)


def write_json(payload: Dict[str, Any], out_path: Path) -> None:
    with out_path.open("w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--input_dir", type=str, required=True, help="Directory containing KTP_eval_run JSON files")
    ap.add_argument("--out_dir", type=str, required=True, help="Directory where aggregated outputs will be saved")
    args = ap.parse_args()

    input_dir = Path(args.input_dir).resolve()
    out_dir = Path(args.out_dir).resolve()
    safe_mkdir(out_dir)

    if not input_dir.exists():
        raise FileNotFoundError(f"Input directory not found: {input_dir}")

    all_rows = collect_all_rows(input_dir)

    if len(all_rows) == 0:
        raise RuntimeError(f"No valid evaluation JSON files found in: {input_dir}")

    rows_overall = [r for r in all_rows if str(r.get("seq", "")) == "ALL"]
    rows_per_sequence = [r for r in all_rows if str(r.get("seq", "")) != "ALL"]

    rows_overall_ranked = sorted(rows_overall, key=sort_key_overall)
    best_per_backend = choose_best_per_backend(rows_overall)

    flat_csv = out_dir / "aggregated_all_rows.csv"
    flat_json = out_dir / "aggregated_all_rows.json"
    overall_csv = out_dir / "aggregated_overall_ranked.csv"
    best_backend_csv = out_dir / "aggregated_best_per_backend.csv"
    per_seq_csv = out_dir / "aggregated_per_sequence.csv"

    write_csv(all_rows, flat_csv)
    write_csv(rows_per_sequence, per_seq_csv)
    write_csv(rows_overall_ranked, overall_csv)
    write_csv(best_per_backend, best_backend_csv)

    payload = {
        "num_total_rows": len(all_rows),
        "num_overall_rows": len(rows_overall),
        "num_per_sequence_rows": len(rows_per_sequence),
        "rows_all": all_rows,
        "rows_overall_ranked": rows_overall_ranked,
        "best_per_backend": best_per_backend,
    }
    write_json(payload, flat_json)

    print("\n[done]")
    print("  aggregated all rows csv   :", flat_csv)
    print("  aggregated per-seq csv    :", per_seq_csv)
    print("  aggregated overall csv    :", overall_csv)
    print("  best per backend csv      :", best_backend_csv)
    print("  aggregated json           :", flat_json)

    print("\nBest run per backend:")
    for row in best_per_backend:
        print(
            f"  backend={row.get('reid_backend')} | "
            f"thr={row.get('reid_thr')} | "
            f"mota={float(row.get('mota', 0.0)):.4f} | "
            f"idsw={int(float(row.get('id_switches', 0)))} | "
            f"recall={float(row.get('recall', 0.0)):.4f} | "
            f"precision={float(row.get('precision', 0.0)):.4f} | "
            f"reacq_mean={float(row.get('reacq_mean_frames', 0.0)):.4f}"
        )

    print("\nOverall ranking:")
    for i, row in enumerate(rows_overall_ranked, start=1):
        print(
            f"  #{i} "
            f"{row.get('reid_backend')} thr={row.get('reid_thr')} | "
            f"mota={float(row.get('mota', 0.0)):.4f} | "
            f"idsw={int(float(row.get('id_switches', 0)))} | "
            f"recall={float(row.get('recall', 0.0)):.4f} | "
            f"precision={float(row.get('precision', 0.0)):.4f}"
        )


if __name__ == "__main__":
    main()